import { Cart, CartItem, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Update existing cart line item(s). This includes a change of quantity of an existing item, which must be the absolute quantity after update.
*/
export type UpdateCart = {
    events: Array<Cart | CartItem | Identity | PartyIdentification | ErrorEvent>;
}

export class UpdateCartBuilder {

    private updateCart: UpdateCart = {
        events: []
    }

    private cart!: Cart;
    private cartItem!: CartItem;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : UpdateCartBuilder {
        this.cart = cart;
        return this;
    }
    public withCartItem(cartItem: CartItem) : UpdateCartBuilder {
        this.cartItem = cartItem;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : UpdateCartBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : UpdateCartBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : UpdateCartBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : UpdateCart {
        if(this.cart) {
            this.updateCart.events.push(this.cart);
        }
        if(this.cartItem) {
            this.updateCart.events.push(this.cartItem);
        }
        if(this.errorEvent) {
            this.updateCart.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.updateCart.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.updateCart.events.push(this.partyIdentification);
        }

        return this.updateCart;
    }
}
